class DesktopClient(Client):
    """
    Класс для обертки API
    """

    poll = True

    def __init__(
        self,
        uin: str,
        phone: Optional[str] = None,
        code: Optional[str] = None,
        api_url: str = "https://u.icq.net",
        binary_api_url: str = "https://ub.icq.net",
        api_ver: int = 92,
        env: env_types = "SANDBOX",
        email_password: Optional[str] = None,
        email_url: Optional[str] = None,
        forced_ip: Optional[str] = None,
        session: Session = None,
        fix_otp: Optional[str] = None,
        org_struct_admin_token: Optional[str] = None,
        assert_caps: Optional[list[str]] = None,
        interest_caps: Optional[list[str]] = [  # noqa
            "8eec67ce70d041009409a7c1602a5c84",
            "094613504c7f11d18222444553540000," "094613514c7f11d18222444553540000",
            "094613503c7f11d18222444553540000",
        ],
        language: Literal["en-GB", "en-US", "ru-RU", "de-DE", "pt-PT"] = "ru-RU",
        sso: bool = False,
        swa: bool = False,
        polling: bool = False,
        check_response: bool = True,
        token: Optional[str] = None,
        aimsid: Optional[str] = None,
        fetch_url: Optional[str] = None,
        *args,  # noqa
        **kwargs,  # noqa
    ):
        if session is None:
            session = Session()

        Client.__init__(
            self,
            session=session,
            api_url=api_url,
            binary_api_url=binary_api_url,
            api_ver=api_ver,
            org_struct_admin_token=org_struct_admin_token,
            forced_ip=forced_ip,
            assert_caps=assert_caps,
            interest_caps=interest_caps,
            language=language,
            check_response=check_response,
        )

        self.session.verify = False
        self.events = []

        self.uin = uin.lower()

        self.phone = phone
        self.code = code

        self.env = env
        self.sso = sso
        self.swa = swa

        self.email_url = email_url
        self.email_password = email_password

        self.fix_otp = fix_otp

        self.login_data = {}

        if token and aimsid and fetch_url:
            self.token = token
            self.aimsid = aimsid
            self.fetch_url = fetch_url
            self.session_started = True
        else:
            assert self.uin

            if self.env != "SANDBOX" and not self.sso:
                assert self.email_url, "Email URL is required to start session"
                assert self.email_password, "Email password is required to start session"

            self.login()

        self.running = False
        self.rewrite_fetch_timeout = 30000
        self.__lock = Lock()
        self.__polling_thread = None
        if polling:
            self.polling()

    @tracer.start_as_current_span("desktop.extract_session_data")
    def extract_session_data(self):
        return {
            "token": self.token,
            "aimsid": self.aimsid,
            "fetch_url": self.fetch_url,
        }

    def __str__(self):
        return f"{self.env}({self.uin})"

    def __repr__(self):
        return f"{self.env}({self.uin})"

    def __enter__(self):
        self.rewrite_fetch_timeout = 1000
        return self

    def __exit__(self, exc_type, exc_val, exc_tb):
        self.kill_polling_thread()
        self.wim_aim_endSession()

    @tracer.start_as_current_span("desktop.login")
    def login(self):
        MAX_RETRIES_COUNT = 3

        if self.env == "SANDBOX" and self.sso:
            self.sign_in_with_sso(redirect=self.api_url.replace("u", "webim", 1))
        elif self.env in ["SAAS", "PRE_SAAS"] and self.sso:
            self.sign_in_with_sso(redirect="https://myteam.mail.ru/webim/")
        elif self.env == "PRE_TARM" and self.swa:
            self.sign_in_with_swa(redirect="https://webim.tppr.vmailru.net/")
        elif self.env == "TARM" and self.swa:
            self.sign_in_with_swa(redirect="https://webim.armgs.team/")
        else:
            for i in range(MAX_RETRIES_COUNT):
                try:
                    otp_token = self.get_otp_token()
                    result = self.wim_auth_clientLogin(otp_token)

                    self.login_data = result["response"]["data"]
                    self.token = self.login_data["token"]["a"]

                    self.restart_session()
                    return
                except Exception as error:
                    if i == MAX_RETRIES_COUNT - 1:
                        raise error

                    self.logger.exception(error, exc_info=True)

    @tracer.start_as_current_span("desktop.sign_in_with_sso")
    def sign_in_with_sso(self, redirect: str):
        """
        Вход с использованием SSO через Keycloak
        """
        rnd_state = str(randint(10000, 99999))

        response = self.idm_auth_authorize(
            client_id=self.devId,
            response_type="code",
            scope="openid",
            state=rnd_state,
            login_hint=self.uin,
            redirect_uri=redirect,
            _type="SSO",
        )

        # Получение кук в keycloak
        response = self.request(
            method="GET",
            url=response.headers["location"],  # noqa
        )

        # Получение URL из формы авторизации в keycloak
        soup = BeautifulSoup(response.text, "html.parser")
        action_url = soup.find(id="kc-form-login").attrs["action"]

        # Авторизация в keycloak
        response = self.request(
            method="POST",
            url=action_url,
            data={
                "username": self.uin,
                "password": self.fix_otp,
            },
            allow_redirects=False,
        )

        # Вызов callback
        response = self.request(
            method="GET",
            url=response.headers["location"],  # noqa
            allow_redirects=False,
        )

        url = urlparse(response.headers["location"])  # noqa
        parsed_query = dict(parse_qsl(url.query))

        response = self.idm_auth_token(
            client_id=self.devId,
            client_secret=self.devId,
            grant_type="authorization_code",
            code=parsed_query["code"],
            state=rnd_state,
            redirect_uri="https://myteam.mail.ru/webim/",
            scope="openid",
        )

        self.token = response["access_token"]
        self.refresh_token = response["refresh_token"]
        self.id_token = response["id_token"]
        self.token_type = response["token_type"]

        self.restart_session_with_SSO()

    @tracer.start_as_current_span("desktop.sign_in_with_swa")
    def sign_in_with_swa(self, redirect: str):
        """
        Вход с использованием SWA через Keycloak
        """
        rnd_state = str(randint(10000, 99999))

        response = self.idm_auth_authorize(
            client_id=self.devId,
            response_type="code",
            scope="openid",
            state=rnd_state,
            login_hint=self.uin,
            redirect_uri=redirect,
        )

        # Получение кук в keycloak
        response = self.request(
            method="GET",
            url=response.headers["location"],  # noqa
        )

        url = urlparse(response.url)  # noqa
        domain = url[1].replace("u.", "", 1)

        response = self.request(
            method="GET",
            url=response.url,
            allow_redirects=False,
        )

        response = self.idm_provider_list(email=self.uin)
        type_swa = response["results"]["providers"][0]["type"]

        response = self.idm_auth_authorize(
            client_id=self.devId,
            response_type="code",
            scope="openid",
            state=rnd_state,
            login_hint=self.uin,
            redirect_uri=redirect,
            _type=type_swa,
        )

        # Получение кук в keycloak
        response = self.request(
            method="GET",
            url=response.headers["location"],  # noqa
        )

        response = self.request(
            method="GET",
            url=response.url,
        )

        response = self.request(
            method="GET",
            url=f"https://account.{domain}/login",
        )

        response = self.request(
            method="POST",
            url=f"https://auth.{domain}/api/v1/pushauth/info",
            data={
                "login": self.uin,
            },
        )

        response = self.request(
            method="POST",
            url=f"https://auth.{domain}/cgi-bin/auth?platform=touch&project=login",
            data={
                "Login": self.uin,
                "Password": self.fix_otp,
            },
        )

        response = self.request(method="GET", url=response.url)

        # Вызов callback
        response = self.request(
            method="GET",
            url=response.headers["location"],  # noqa
            allow_redirects=False,
        )

        url = urlparse(response.headers["location"])  # noqa
        parsed_query = dict(parse_qsl(url.query))

        response = self.idm_auth_token(
            client_id=self.devId,
            client_secret=self.devId,
            grant_type="authorization_code",
            code=parsed_query["code"],
            state=rnd_state,
            redirect_uri="https://myteam.mail.ru/webim/",
            scope="openid",
        )

        self.token = response["access_token"]
        self.refresh_token = response["refresh_token"]
        self.id_token = response["id_token"]
        self.token_type = response["token_type"]

        self.restart_session_with_SWA()

    @tracer.start_as_current_span("desktop.sign_in_with_phone")
    def sign_in_with_phone(self):
        """
        Готовая функция для входа по телефону
        :return:
        """
        result = self.smsreg_requestPhoneValidation()["response"]["data"]
        self.trans_id = result["trans_id"]

        result = self.smsreg_loginWithPhoneNumber()["response"]["data"]
        self.token = result["token"]["a"]

        result = self.wim_aim_startSession()
        self.aimsid = result["response"]["data"]["aimsid"]
        self.fetch_url = result["response"]["data"]["fetchBaseURL"]
        self.uin = result["response"]["data"]["myInfo"]["aimId"]

        self.session_started = True

    @tracer.start_as_current_span("desktop.polling")
    def polling(self):
        with self.__lock:
            if self.__polling_thread is None or not self.__polling_thread.is_alive():
                self.logger.info("Starting polling.")

                self.__polling_thread = Thread(target=self.continues_fetch, daemon=True)

                self.running = True
                self.__polling_thread.start()

    @tracer.start_as_current_span("desktop.continues_fetch")
    def continues_fetch(self):
        assert self.fetch_url

        while DesktopClient.poll:
            self.fetch(timeout=self.rewrite_fetch_timeout)

    @tracer.start_as_current_span("desktop.kill_polling_thread")
    def kill_polling_thread(self):
        if self.__polling_thread is not None and self.__polling_thread.is_alive():
            with self.__lock:
                DesktopClient.poll = False

                self.__polling_thread.join()

    @tracer.start_as_current_span("desktop.get_otp_token")
    def get_otp_token(self, exec_local: bool = True) -> str:
        self.logger.info(f"ENV: {self.env}")

        if (self.env == "SANDBOX" and "@autotest.clients" in self.uin) or self.fix_otp is not None:
            self.wim_auth_clientLoginFirst()
            return self.fix_otp

        elif self.env == "SANDBOX":
            if exec_local:
                return self.get_otp_token_from_chat_local()
            else:
                return self.get_otp_token_from_chat()

        elif self.env == "ICQ":
            return "402457"

        elif self.env in ["VKTI", "PRE_VKTI", "TARM", "PRE_TARM", "SAAS", "PRE_SAAS"]:
            if exec_local:
                return self.get_otp_token_from_mail_local(
                    password=self.email_password,
                    imap_url=self.email_url,
                    invoke_token=True,
                )
            else:
                return self.get_otp_token_from_mail(
                    password=self.email_password,
                    imap_url=self.email_url,
                    invoke_token=True,
                )

        else:
            raise ValueError(f"Unknown env value: {self.env}")

    @tracer.start_as_current_span("desktop.delete_last_groups")
    def delete_last_groups(self) -> tuple[bool, Optional[Exception]]:
        """
        Удаление последних чатов
        :return: результат операции
        """
        for _ in range(10):
            self.fetch()

            try:
                chats_set = set()

                for event in filter(lambda x: x["type"] == "buddylist", self.events):
                    for group in event["eventData"]["groups"]:
                        for buddy in group["buddies"]:
                            chats_set.add(buddy["aimId"])

                for chat_id in chats_set:
                    self.wim_buddyList_hideChat(buddy=chat_id, lastMsgId=1)
                    self.wim_buddyList_removeBuddy(buddy=chat_id)

                return True, None
            except Exception as error:
                self.logger.error(error)
                return False, error

    @tracer.start_as_current_span("desktop.delete_last_drafts")
    def delete_last_drafts(self) -> tuple[bool, Optional[Exception]]:
        """
        Удалить последние черновики
        :return: результат операции
        """
        try:
            self.fetch()

            chats_with_draft_list = {
                filtered_event["eventData"]["sn"] for filtered_event in self.events if filtered_event["type"] == "draft"
            }

            for chat_id in chats_with_draft_list:
                self.rapi_draft_set(sn=chat_id, parts=[])

            return True, None
        except Exception as error:
            self.logger.error(error)
            return False, error

    @tracer.start_as_current_span("desktop.clear_contacts_list")
    def clear_contacts_list(self) -> tuple[bool, Optional[Exception]]:
        try:
            response = self.rapi_contacts_get()

            contacts = [x["sn"] for x in response["results"]["contacts"]]

            errors = []

            def chunks(lst: list[str], n: int):
                """Yield successive n-sized chunks from lst."""
                for i in range(0, len(lst), n):
                    yield lst[i : i + n]

            for contacts_slice in chunks(contacts, 10):
                try:
                    self.rapi_contacts_delete(targets=contacts_slice)

                except Exception as error:
                    errors.append(error)

            if errors:
                raise ExceptionGroup("Errors on cleaning contact list", errors)  # noqa: F821

            return True, None
        except Exception as error:
            return False, error

    @tracer.start_as_current_span("desktop.clear_contacts_black_list")
    def clear_contacts_black_list(self) -> tuple[bool, Optional[Exception]]:
        """
        Удалить всех из черного списка
        :return: результат операции
        """
        try:
            black_list = self.rapi_privacy_groups_inviteBlacklist_get(100)["results"]
            if black_list.get("blacklist", []):
                self.rapi_privacy_groups_inviteBlacklist_del(black_list["blacklist"])
            if black_list.get("persons", []):
                self.rapi_privacy_groups_inviteBlacklist_del([user["sn"] for user in black_list["persons"]])

            black_list = self.rapi_privacy_groups_inviteBlacklist_getBlacklistedContacts()
            if black_list["results"].get("blacklist", []):
                self.rapi_privacy_groups_inviteBlacklist_del(black_list["results"]["blacklist"])
            return True, None
        except Exception as error:
            return False, error

    @tracer.start_as_current_span("desktop.clear_permit_deny_list")
    def clear_permit_deny_list(self) -> tuple[bool, Optional[Exception]]:
        try:
            errors_list = []

            response = self.wim_preference_getPermitDeny()

            ignore_list = response["response"]["data"].get("ignores", [])

            for person in ignore_list:
                try:
                    self.wim_preference_setPermitDeny(pdIgnoreRemove=person)
                except Exception as error:
                    self.logger.warning(error)
                    errors_list.append(error)

            if errors_list:
                raise ExceptionGroup("Errors on unblocking persons", errors_list)  # noqa: F821

            return True, None
        except Exception as error:
            return False, error

    @tracer.start_as_current_span("desktop.clear_tasks")
    def clear_tasks(self):
        try:
            for task in self.iter_task_list_for_clean():
                if not task["isRead"]:
                    self.tasks_setRead(tasks=[task["taskId"]])

                if task["creator"] == self.uin and task["status"] != "ready":
                    self.tasks_edit(
                        taskId=task["taskId"],
                        status="ready",
                        endTime=int(datetime.now().timestamp()) + 10,
                    )

            return True, None
        except Exception as error:
            return False, error

    @tracer.start_as_current_span("desktop.clear_deny_list")
    def clear_deny_list(self) -> bool:
        """
        Удалить всех из списка игнорируемых
        """
        try:
            blocked = self.wim_preference_getPermitDeny()

            for sn in blocked.get("ignores", []):
                self.wim_preference_setPermitDeny(pdIgnoreRemove=sn)
            return True
        except RequestException:
            return False

    @tracer.start_as_current_span("desktop.read_last_msg")
    def read_last_msg(self) -> bool:
        """
        Прочитать последние сообщения
        :return: результат операции
        """
        try:
            buddyList_event = None
            for event in filter(lambda x: x["type"] == "buddylist", self.events):
                buddyList_event = event["eventData"]["groups"]
                break

            temp = []

            for buddies in buddyList_event:
                if buddies["name"] == "Temporarily":
                    temp = buddies["buddies"]

            for buddy in temp:
                try:
                    self.send_basic_message(sn=buddy["aimId"], text="read")
                except RequestException as error:
                    self.logger.error(error)
            return True
        except Exception as error:
            self.logger.error(error)
            return False

    @tracer.start_as_current_span("desktop.restore_privacy_settings")
    def restore_privacy_settings(self) -> tuple[bool, Optional[Exception]]:
        """
        Вернуть настройки приватности к базовому состоянию
        :return: результат операции
        """
        try:
            privacy_settings = self.rapi_getPrivacySetting()["results"]

            if privacy_settings["calls"]["allowTo"] != "everybody":
                self.rapi_updatePrivacySettings(privacy="calls", permission="everybody")
            if privacy_settings["groups"]["allowTo"] != "everybody":
                self.rapi_updatePrivacySettings(privacy="groups", permission="everybody")
            return True, None
        except Exception as error:
            self.logger.error(error)
            return False, error

    @tracer.start_as_current_span("desktop.get_chat_stamp")
    def get_chat_stamp(self, _id: str) -> str:
        """
        Получить уникальный stamp группы/канала
        :param _id: ID чата
        :return: результат операции
        """
        response = self.rapi_getIdInfo(_id)

        return response["results"]["chat"]["stamp"]

    @tracer.start_as_current_span("desktop.create_chat")
    def create_chat(
        self,
        name: str = "Test group - autotest.release",
        avatarId: str = "",
        members: list[Union[str, "DesktopClient"]] = (),
        about: str = "Something new about this group",
        rules: str = "Some rules of this group",
        public: bool = False,
        joinModeration: bool = True,
        defaultRole: Literal["member", "admin", "readonly"] = "member",
        check_members: bool = True,
    ) -> str:
        """
        Модификация уже созданного чата
        :param name: Новое имя чата
        :param avatarId: ID аватара чата
        :param members: список пользователей
        :param about: Новое описание чата
        :param rules: Новые правила чата
        :param public: Флаг публичности чата
        :param joinModeration: Флаг премодерации на вступление в чат
        :param defaultRole: базовая роль пользователя при вступлении
        :param check_members:
        проверки доверенности пользователя в чате
        :return: ID созданного чата
        """
        for member in members:
            self.send_basic_message(
                sn=member.uin if isinstance(member, DesktopClient) else member,
                text=f'Adding you to chat "{name}"',
            )

        chat_response = self.rapi_createChat(
            name,
            avatarId,
            [member.uin if isinstance(member, DesktopClient) else member for member in members],
            about,
            rules,
            public,
            joinModeration,
            defaultRole,
        )

        chat_sn = chat_response["results"]["sn"]

        self.created_chats.add(chat_sn)
        self.check_empty_create_chat(chat_sn)

        if check_members:
            chat_info = self.rapi_getChatInfo(sn=chat_sn, memberLimit=len(members) + 1)

            members_list = [x["sn"] for x in chat_info["results"]["members"]]

            for person in members:
                try:
                    if isinstance(person, DesktopClient):
                        assert person.uin in members_list, (
                            f"{self.env}:/api/v{self.api_ver}/rapi/createChat:"
                            f"member_not_in_chat:"
                            f"creator-{self.uin}:member-{person}"
                        )
                    else:
                        assert person in members_list, (
                            f"{self.env}:/api/v{self.api_ver}/rapi/createChat:"
                            f"member_not_in_chat:"
                            f"creator-{self.uin}:member-{person}"
                        )
                except AssertionError:
                    try:
                        self.rapi_group_members_add(
                            sn=chat_sn,
                            members=[person.uin if isinstance(person, DesktopClient) else person],
                        )
                    except UserMustJoinByLinkException:
                        if isinstance(person, DesktopClient):
                            person.restore_privacy_settings()
                            person.rapi_joinChat(stamp=chat_info["results"]["stamp"])
                        else:
                            raise

            if defaultRole == "readonly":
                for member in filter(
                    lambda x: x.uin != self.uin if isinstance(x, DesktopClient) else x != self.uin,
                    members,
                ):
                    self.rapi_modChatMember(
                        memberSn=member.uin if isinstance(member, DesktopClient) else member,
                        sn=chat_sn,
                    )
        return chat_sn

    @tracer.start_as_current_span("desktop.add_thread")
    def add_thread(self, chat_id: str, msg_id: Union[str, int]) -> str:
        thread_add_response = self.rapi_thread_add(chatId=chat_id, messageId=msg_id)
        thread_id = thread_add_response["results"]["threadId"]

        self.rapi_thread_subscribe(threadId=thread_id)

        self.rapi_group_subscribe(chatId=thread_id)

        self.rapi_eventSubscribe(subscriptions=[{"type": "threadUpdate", "data": {"threads": [thread_id]}}])

        return thread_id

    @tracer.start_as_current_span("desktop.task_add_by_sendIM")
    def task_add_by_sendIM(
        self,
        chat_id: str,
        title: str = "test",
        assignee: Optional[str] = None,
        endTime: Union[int, float] = (datetime.now() + timedelta(days=5)).timestamp(),
        status: str = "new",
        priority: str = "critical",
        label: str = "none",
        tags: Union[tuple[str, ...], list[str]] = (),
        schedule: Optional[dict[str, int]] = None,
    ) -> tuple[Any, Any]:
        response = self.wim_im_sendIM(
            t=chat_id,
            parts=[
                {
                    "mediaType": "text",
                    "text": "test",
                    "task": {
                        "title": title,
                        "assignee": assignee,
                        "endTime": endTime,
                        "creator": self.uin,
                        "status": status,
                        "priority": priority,
                        "label": label,
                        "tags": tags,
                    },
                },
            ],
            schedule=schedule,
        )

