    @tracer.start_as_current_span("desktop.add_task_filter")
    def add_task_filter(
        self,
        name: str,
        assignees: [tuple[str, ...], list[str]] = (),
        statuses: [tuple[str, ...], list[str]] = (),
        deadline: Optional[str | datetime] = None,
        subscribed: bool = False,
        withChanges: bool = False,
    ) -> str:
        if deadline is None:
            deadline = datetime.now() + timedelta(days=5)

        for i in range(4):
            response = self.tasks_filters_add(
                name=name,
                assignees=assignees,
                statuses=statuses,
                deadline=deadline,
                subscribed=subscribed,
                withChanges=withChanges,
            )

            if response["status"]["code"] == 20000:
                filter_id = response["results"]["id"]
                break
            time.sleep(i)
        else:
            raise ValueError("Failed to get filter_id")

        self.rapi_eventSubscribe(subscriptions=[{"type": "filterList", "data": {"filters": [filter_id]}}])

        return filter_id

    @tracer.start_as_current_span("desktop.iter_task_list")
    def iter_task_list(self, filter_name: str = "Все", page_size: int = 20):
        try:
            filters_list_response = self.tasks_filters_list()
            filters_list = filters_list_response["results"]["filters"]

            filter_index = [x["name"] for x in filters_list].index(filter_name)

            filter_id = filters_list[filter_index]["id"]
        except ValueError:
            filter_create_response = self.tasks_filters_add(
                name="Все", statuses=["new", "in_progress", "ready", "rejected"]
            )
            filter_id = filter_create_response["results"]["id"]

        fetch_tasks = True

        cursor = None

        counter = 0

        while fetch_tasks and counter < 20:
            counter += 1

            task_list_response = self.tasks_list(_filter=filter_id, cursor=cursor, pageSize=page_size)
            result = task_list_response["results"]

            cursor = result.get("cursor")

            if not result.get("tasks", []):
                break

            for task in result.get("tasks", []):
                yield task

            if cursor is None:
                break

    @tracer.start_as_current_span("desktop.iter_task_list_for_clean")
    def iter_task_list_for_clean(self, page_size: int = 20):
        response: dict[str, Any] = self.post(
            "tasks/filters/add",
            json={
                "reqId": self.getReqId(),
                "aimsid": self.aimsid,
                "params": {
                    "name": "Все",
                    "statuses": [
                        "new",
                        "in_progress",
                        "ready",
                        "rejected",
                        "closed",
                    ],
                },
            },
        )

        filter_id = response["results"]["id"]

        fetch_tasks = True

        cursor = None

        counter = 0

        while fetch_tasks and counter < 20:
            counter += 1

            task_list_response = self.tasks_list(_filter=filter_id, cursor=cursor, pageSize=page_size)
            result = task_list_response["results"]

            cursor = result.get("cursor")

            if not result.get("tasks", []):
                break

            for task in result.get("tasks", []):
                yield task

            if cursor is None:
                break
        try:
            self.tasks_filters_delete(filter_id=filter_id)
        except Exception as error:
            self.logger.error(error)

    @tracer.start_as_current_span("desktop.iter_thread_list")
    def iter_thread_list(self, filter_type: str = "all", page_size: int = 20):
        fetch_tasks = True

        response = self.rapi_thread_feed_get(filter_type=filter_type, pageSize=page_size)
        result = response["results"]

        while fetch_tasks:
            cursor = result.get("cursor")

            if not result.get("threads", []):
                break

            for thread in result["threads"]:
                yield thread

            if cursor is None:
                break

            response = self.rapi_thread_feed_get(filter_type=filter_type, cursor=cursor, pageSize=page_size)
            result = response["results"]

