    @tracer.start_as_current_span("desktop.forward_message")
    def forward_message(
        self,
        sn: str,
        author_sn: str,
        quote: str,
        msg_id: int,
        old_sn: Optional[str] = None,
        text: Optional[str] = None,
        schedule: Optional[dict[str, int]] = None,
    ) -> int:
        """
        Отправка сообщения в виде реплая
        :param sn: чат, куда нужно отправить сообщение
        :param author_sn: автор исходного сообщения
        :param quote: текст исходного сообщения
        :param msg_id: ID исходного сообщения, на которое делается реплай
        (не верифицируется)
        :param old_sn: исходный чат, откуда пересылается сообщение
        :param text: текст ответа
        :param schedule: объект для запланированных - состоит из 2 полей
            scheduledTime - обязательное поле, timestamp запланированного времени отправки
            updateScheduledMsgId - используется для редактирования запланированного в очереди
        :return: msgId
        """
        forward_part = {
            "mediaType": "forward",
            "text": quote,
            "sn": author_sn,
            "msgId": msg_id,
            "time": int(datetime.now().timestamp()),
        }
        if old_sn and old_sn.endswith("@chat.agent"):
            forward_part.update(
                {
                    "chat": {
                        "sn": old_sn,
                        "stamp": self.get_chat_stamp(old_sn),
                    }
                }
            )

        parts = [forward_part]
        if text:
            parts.append({"mediaType": "text", "text": text})

        response = self.wim_im_sendIM(
            t=sn,
            parts=parts,
            schedule=schedule,
        )

        return response["response"]["data"]["histMsgId"]

    @tracer.start_as_current_span("desktop.forward_message_by_message_send")
    def forward_message_by_message_send(
        self,
        target: str,
        author_sn: str,
        plain_to_forward: str,
        msg_id: int,
        chat_sn_to_forward_from: Optional[str] = None,
        chat_stamp: Optional[str] = None,
        need_stamp: bool = True,
        chat_name: Optional[str] = None,
        forward_parts: Optional[list[dict]] = None,
        plain_text: Optional[str] = None,
        main_part: Optional[dict] = None,
        update_msg_id: Optional[int] = None,
        schedule: Optional[dict[str, int]] = None,
    ) -> int:
        """
        Отправка сообщения в виде реплая
        :param target: чат, куда нужно отправить сообщение
        :param author_sn: автор исходного сообщения
        :param plain_to_forward: текст исходного сообщения
        :param chat_sn_to_forward_from: исходный чат, откуда пересылается сообщение
        :param msg_id: ID исходного сообщения, на которое делается реплай
        (не верифицируется)
        :param chat_stamp: Внутренний идентификатор чата на бекенде
        :param need_stamp: Автоматиечски добавить stamp при пересылке сообщения из чата
        :param forward_parts: массив парстов для пересылки
        :param plain_text: текст ответа
        :param main_part: парт для ответа на сообщение
        :param update_msg_id: Id редактируемого сообщения
        :param schedule: объект для запланированных - состоит из 2 полей
            scheduledTime - обязательное поле, timestamp запланированного времени отправки
            updateScheduledMsgId - используется для редактирования запланированного в очереди
        :return: msgId
        """
        if plain_text:
            main_part = {"text": {"plain": plain_text}}
        forward_part = {
            "text": {"plain": plain_to_forward},
            "sn": author_sn,
            "msgId": msg_id,
            "time": int(datetime.now().timestamp()),
        }

        if chat_sn_to_forward_from and chat_sn_to_forward_from.endswith("@chat.agent"):
            forward_part["chat"] = {
                "sn": chat_sn_to_forward_from,
            }
            if chat_stamp:
                forward_part["chat"]["stamp"] = chat_stamp
            elif need_stamp:
                forward_part["chat"]["stamp"] = self.get_chat_stamp(chat_sn_to_forward_from)
            if chat_name:
                forward_part["chat"]["name"] = chat_name

        response = self.rapi_message_send(
            target=target,
            schedule=schedule,
            updateMsgId=update_msg_id,
            parts={
                "mainPart": main_part,
                "forwardParts": forward_parts if forward_parts else [forward_part],
            },
        )
        if schedule:
            status_code = response["status"]["code"]
            if status_code == 20020:
                return response["results"]["scheduled"]["scheduledMsgId"]
            elif status_code != 20021:
                raise ValueError("Invalid response! Expected [20020|20021], got[" + str(status_code) + "]")

        return response["results"]["msgId"]

