class CallGuestClient(GuestClient):
    def __init__(
        self,
        name: str,
        scopes: list[str],
        env: env_types = "SANDBOX",
        *args,
        **kwargs,
    ):
        GuestClient.__init__(self, *args, **kwargs)

        self.name = name
        self.scopes = scopes
        self.env = env

        response = self.rapi_auth_guest(name=name, scopes=scopes)

        results = response["results"]

        self.token = results["token"]
        self.uin = results["sn"]

        result = self.wim_aim_startSession()
        self.aimsid = result["response"]["data"]["aimsid"]
        self.fetch_url = result["response"]["data"]["fetchBaseURL"]
        self.session_started = True

        self.events: list[dict[str, Any]] = []

    @tracer.start_as_current_span("guest.clean_account")
    def upload_file(self, file_path: str, _type: Optional[str] = None) -> tuple[str, dict]:
        """
        Загружает файл в мессенджер.
        Содержит ассерты для проверки успешности операции.

        :return: file_id, result
        """
        file_path = pathlib.Path(file_path)

        file_name = file_path.name
        file_size = file_path.stat().st_size

        result = self.files_init(filename=file_name, size=file_size, _type=_type)
        status_code = result["status"]["code"]

        assert status_code == 200, "Не удалось инициировать загрузку файла (files/init): " "код ответа: {}".format(
            status_code,
        )

        f_result: dict[str, Any] = self.request(
            method="POST",
            url="https://{host}{url}".format(**result["result"]),
            headers={"Content-Range": f"bytes 0-{file_size - 1}/{file_size}"},
            params={
                "aimsid": self.aimsid,
                "f": "json",
                "k": self.devId,
                "size": file_size,
                "client": "myteam",
            },
            data=read_in_chunks(file_path),
        )
        status_code = f_result["status"]["code"]

        assert status_code == 200, "Ошибка во время загрузки файла (file/upload): " "код ответа: {}".format(status_code)

        return f_result["result"]["fileid"], f_result["result"]

    @tracer.start_as_current_span("guest.get_error_message")
    def get_error_message(
        self,
        path_url: str,
        response_status_code: Union[str, int],
        response_status_text: str,
    ) -> str:
        return f'{self.env}:{path_url.split("?")[0]}:{response_status_code}:{response_status_text}'

    @tracer.start_as_current_span("guest.fetch")
    def fetch(self, rewrite: bool = True, timeout: int = 1000):
        response = self.bos_fetchEvents(rewrite, timeout)

        events = response["response"]["data"]["events"]

        for event in events:
            event["timestamp"] = datetime.now()
            self.events.append(event)

        return events
